/* engines/amplitude.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "../context.js";

export function install(P) {


  /* AmplitudeJS keeps its own private Audio for event wiring, but after init
     its config points at the shared element. That lets Amplitude issue the
     play/pause commands without its internal "next song" handlers touching
     our queue. */
  async function createAmplitude(url, startAt, autoplay) {
    try { await P.loadAmplitudeScript(); } catch {
      P.fallbackToHtml5();
      P.notify("engine");
      return false;
    }
    if (!window.Amplitude) {
      P.fallbackToHtml5();
      P.notify("engine");
      return false;
    }

    P.showEngineUi("amplitude");
    try {
      window.Amplitude.init({
        songs: [{ name: P.state.current?.title || "zqwy", artist: "zqwy", url }],
        continue_next: false,
        volume: Math.round(P.state.volume * 100),
        debug: false,
      });
      const config = window.Amplitude.getConfig();
      config.audio = P.audio;
      if (config.songs?.[0]) config.active_metadata = config.songs[0];
    } catch {
      P.fallbackToHtml5();
      P.notify("engine");
      return false;
    }
    P.audio.src = url;
    P.audio.load();
    if (startAt) P.setTime(startAt);
    if (autoplay) P.attemptPlay();
    return true;
  }
  Object.assign(P, { createAmplitude });
}
